#include <bits/stdc++.h>
using namespace std;

static string in;
static size_t p = 0;
static void readAll() {
    char b[1 << 16];
    size_t k;
    while ((k = fread(b, 1, sizeof b, stdin)) > 0) in.append(b, k);
}
static bool skipSpace() {
    while (p < in.size() && (unsigned char)in[p] <= ' ') p++;
    return p < in.size();
}
static string token() {
    skipSpace();
    size_t s = p;
    while (p < in.size() && (unsigned char)in[p] > ' ') p++;
    return in.substr(s, p - s);
}
static long long num() {
    skipSpace();
    bool neg = false;
    if (p < in.size() && (in[p] == '-' || in[p] == '+')) neg = in[p++] == '-';
    long long v = 0;
    while (p < in.size() && in[p] >= '0' && in[p] <= '9') v = v * 10 + (in[p++] - '0');
    return neg ? -v : v;
}

int main() {
    readAll();
    num();  // n: every following number is a user ID
    vector<long long> ids;
    while (skipSpace()) ids.push_back(num());
    int n = ids.size();
    // Compress IDs to 0..k-1 so counts live in an array.
    vector<long long> sorted = ids;
    sort(sorted.begin(), sorted.end());
    sorted.erase(unique(sorted.begin(), sorted.end()), sorted.end());
    vector<int> a(n);
    for (int i = 0; i < n; i++) a[i] = lower_bound(sorted.begin(), sorted.end(), ids[i]) - sorted.begin();
    vector<int> counts(sorted.size(), 0);
    for (int v : a) counts[v]++;
    int target = *min_element(counts.begin(), counts.end());  // f: the global minimum frequency
    fill(counts.begin(), counts.end(), 0);
    // Window keeps every count <= f; `at` = number of users whose count is exactly f.
    int left = 0, answer = 0, at = 0;
    for (int right = 0; right < n; right++) {
        int v = a[right];
        if (counts[v] == target) at--;
        if (++counts[v] == target) at++;
        while (counts[v] > target) {
            int u = a[left++];
            if (counts[u] == target) at--;
            if (--counts[u] == target) at++;
        }
        if (at) answer = max(answer, right - left + 1);
    }
    printf("%d\n", answer);
}

import java.util.Arrays;

public class Main {
    static byte[] data;
    static int pos = 0;

    static boolean skipSpace() {
        while (pos < data.length && (data[pos] & 0xff) <= ' ') pos++;
        return pos < data.length;
    }

    static String token() {
        skipSpace();
        int s = pos;
        while (pos < data.length && (data[pos] & 0xff) > ' ') pos++;
        return new String(data, s, pos - s, java.nio.charset.StandardCharsets.UTF_8);
    }

    static long num() {
        skipSpace();
        boolean neg = false;
        if (pos < data.length && (data[pos] == '-' || data[pos] == '+')) neg = data[pos++] == '-';
        long v = 0;
        while (pos < data.length && data[pos] >= '0' && data[pos] <= '9') v = v * 10 + (data[pos++] - '0');
        return neg ? -v : v;
    }

    public static void main(String[] args) throws Exception {
        data = System.in.readAllBytes();
        num();  // n: every following number is a user ID
        long[] buf = new long[16];
        int n = 0;
        while (skipSpace()) {
            if (n == buf.length) buf = Arrays.copyOf(buf, 2 * n);
            buf[n++] = num();
        }
        // Compress IDs to 0..k-1 so counts live in an array.
        long[] sorted = Arrays.copyOf(buf, n);
        Arrays.sort(sorted);
        int k = 0;
        for (int i = 0; i < n; i++)
            if (i == 0 || sorted[i] != sorted[i - 1]) sorted[k++] = sorted[i];
        int[] a = new int[n], counts = new int[k];
        for (int i = 0; i < n; i++) counts[a[i] = Arrays.binarySearch(sorted, 0, k, buf[i])]++;
        int target = Integer.MAX_VALUE;  // f: the global minimum frequency
        for (int c : counts) target = Math.min(target, c);
        Arrays.fill(counts, 0);
        // Window keeps every count <= f; `at` = number of users whose count is exactly f.
        int left = 0, answer = 0, at = 0;
        for (int right = 0; right < n; right++) {
            int v = a[right];
            if (counts[v] == target) at--;
            if (++counts[v] == target) at++;
            while (counts[v] > target) {
                int u = a[left++];
                if (counts[u] == target) at--;
                if (--counts[u] == target) at++;
            }
            if (at > 0) answer = Math.max(answer, right - left + 1);
        }
        System.out.println(answer);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func skipSpace() bool {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	return pos < len(data)
}

func token() string {
	skipSpace()
	s := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[s:pos])
}

func num() int64 {
	skipSpace()
	neg := false
	if pos < len(data) && (data[pos] == '-' || data[pos] == '+') {
		neg = data[pos] == '-'
		pos++
	}
	var v int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		v = v*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	num() // n: every following number is a user ID
	a := []int64{}
	for skipSpace() {
		a = append(a, num())
	}
	total := map[int64]int{}
	for _, v := range a {
		total[v]++
	}
	target := len(a) // f: the global minimum frequency
	for _, c := range total {
		target = min(target, c)
	}
	// Window keeps every count <= f; `at` = number of users whose count is exactly f.
	counts := map[int64]int{}
	left, answer, at := 0, 0, 0
	for right, v := range a {
		if counts[v] == target {
			at--
		}
		counts[v]++
		if counts[v] == target {
			at++
		}
		for counts[v] > target {
			u := a[left]
			if counts[u] == target {
				at--
			}
			counts[u]--
			if counts[u] == target {
				at++
			}
			left++
		}
		if at > 0 {
			answer = max(answer, right-left+1)
		}
	}
	fmt.Println(answer)
}
